<?php $extraEvents=$data['events']??[]; if(!empty($invitation['id'])): try{$q=db()->prepare('SELECT * FROM dress_codes WHERE invitation_id=? AND enabled=1 LIMIT 1');$q->execute([$invitation['id']]);$dress=$q->fetch();$q=db()->prepare('SELECT * FROM live_streams WHERE invitation_id=? AND enabled=1 LIMIT 1');$q->execute([$invitation['id']]);$live=$q->fetch();$q=db()->prepare('SELECT * FROM wedding_gifts WHERE invitation_id=? AND enabled=1 LIMIT 1');$q->execute([$invitation['id']]);$gift=$q->fetch();$q=db()->prepare('SELECT * FROM gallery_items WHERE gallery_id=(SELECT id FROM gallery WHERE invitation_id=?) AND status=1 ORDER BY sort_order,id');$q->execute([$invitation['id']]);$galleryItems=$q->fetchAll();}catch(Throwable){$dress=$live=$gift=null;$galleryItems=[];} if($dress): ?><section><span class="eyebrow">DRESS CODE</span><h2><?=e($dress['title'])?></h2><p><?=e($dress['description'])?></p></section><?php endif;if($live):?><section><span class="eyebrow">LIVE STREAMING</span><h2><?=e($live['title'])?></h2><a class="button" href="<?=e(safe_url($live['url']))?>" target="_blank" rel="noopener">Watch Live</a></section><?php endif;if($galleryItems):?><section><span class="eyebrow">OUR GALLERY</span><div class="gallery-grid"><?php foreach($galleryItems as $item):?><figure><img loading="lazy" src="/<?=e($item['path'])?>" alt="<?=e($item['caption'])?>"><figcaption><?=e($item['caption'])?></figcaption></figure><?php endforeach;?></div></section><?php endif;if($gift):?><section><span class="eyebrow">GIFT DELIVERY</span><h2><?=e($gift['shipping_name'])?></h2><p><?=nl2br(e($gift['shipping_address']))?></p><button class="button secondary" data-copy="<?=e($gift['shipping_address'])?>">Salin Alamat</button></section><?php endif;?><section><a class="button secondary" href="/calendar/<?=e($invitation['slug'])?>">Add to Calendar</a></section><script src="/assets/js/copy.js"></script><?php endif;?>
